package io.github.jesterportfolio.hearth.survival.housing;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.*;
import java.nio.file.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;
import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.survival.*;
import io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy;
import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;

/** 한 작업/원본 유지 경계의 거주 통합. 상세 수치는 외부 properties에 둡니다. */
public final class HousingRuntime implements AutoCloseable {
 public interface Boundary{Object token(Player p);boolean current(Player p,Object token);boolean available(Player p);void freeze(Player p,Object token,boolean value);void move(Player p,Object token,String label,Supplier<CompletionStage<Location>> target);void returnSpawn(Player p);Location entry(SurvivalWorld role);Map<SurvivalWorld,World> worlds();}
 public enum State{STARTING,READY,HOLD,DRAINED,CLOSED}
 public final JavaPlugin plugin;public final SurvivalEconomy economy;public final HousingSettings settings;public final HousingStore store;public final HousingWorlds worlds;public final Executor owner;public final Boundary boundary;public final HousingProtection protection;
 private volatile Snapshot snapshot=new Snapshot(List.of(),List.of(),Map.of(),List.of(),Map.of());private State state=State.STARTING;private final RuntimeLease.Lease lease;private final Map<UUID,AtomicBoolean> busy=new HashMap<>();private final Map<UUID,AtomicBoolean> changed=new HashMap<>();private final Set<UUID> blocked=new HashSet<>();private boolean operation;private long generation;private final HousingMenu menu;private final HousingAccess access;private final BukkitTask pulse;
 public HousingRuntime(JavaPlugin plugin,UUID group,SurvivalEconomy economy,Boundary boundary)throws Exception{this.plugin=plugin;this.economy=economy;this.boundary=boundary;owner=economy.owner;Path data=plugin.getDataFolder().toPath().toAbsolutePath();String name=plugin.getConfig().getString("housing.content-file","housing.properties");if(name==null||!name.matches("[a-zA-Z0-9_-]+\\.properties"))throw new IllegalArgumentException("HOUSING_CONFIG_PATH");Path file=data.resolve(name);if(!file.equals(file.toRealPath())||Files.size(file)>65536)throw new IllegalStateException("HOUSING_CONFIG_PATH");var p=new Properties();try(var r=Files.newBufferedReader(file)){p.load(r);}settings=HousingSettings.parse(p);lease=RuntimeLease.acquire(data.resolve("housing.active"),"Hearth housing runtime v1\n"+group+"\n").orElseThrow(()->new IllegalStateException("HOUSING_UNCLEAN_HOLD"));store=new HousingStore(economy.database(),economy.store,economy.settings.realm(),settings);protection=new HousingProtection(economy.database(),settings,boundary.entry(SurvivalWorld.RESIDENCE),boundary.worlds(),boundary::entry);worlds=new HousingWorlds(plugin,group,economy.settings.realm(),settings,protection);menu=new HousingMenu(this);access=new HousingAccess(this);pulse=Bukkit.getScheduler().runTaskTimer(plugin,()->{if(state==State.READY&&!operation)worlds.tick();},20,20);}
 public CompletionStage<Void> open(){return store.open().thenCompose(v->store.snapshot()).thenComposeAsync(s->{snapshot=s;return protection.common(s);},owner).thenRunAsync(()->{state=State.READY;generation++;plugin.getLogger().info("HEARTH_HOUSING_READY houses="+snapshot.houses().size());},owner).whenCompleteAsync((v,error)->{if(error!=null)state=State.HOLD;},owner);}
 public State state(){return state;}public long generation(){return generation;}public Snapshot snapshot(){return snapshot;}public boolean busy(UUID p){return busy.containsKey(p);}public boolean ready(Player p){return state==State.READY&&!operation&&!busy(p.getUniqueId())&&boundary.current(p,boundary.token(p))&&boundary.available(p)&&economy.free(p);}
 public Optional<House> house(UUID id){return snapshot.houses().stream().filter(h->h.id().equals(id)).findFirst();}public Optional<House> house(World w){var id=worlds.house(w);return id.flatMap(this::house);}
 public boolean managed(World w){return boundary.worlds().containsValue(w)||worlds.house(w).isPresent();}
 public boolean allowed(UUID player,Location to){var h=house(to.getWorld());if(h.isPresent())return state==State.READY&&!blocked.contains(h.get().id())&&snapshot.enter(player,h.get())&&HousingWorlds.inside(h.get(),to);return boundary.worlds().containsValue(to.getWorld());}
 private java.util.function.BiPredicate<UUID,Location> interaction=(id,at)->false;
 private java.util.function.BiPredicate<Player,Player> rpgPvp;
 public void pvpPolicy(java.util.function.BiPredicate<Player,Player> policy){rpgPvp=policy;}
 public boolean pvpConfigured(){return rpgPvp!=null;}
 public boolean pvpAllowed(Player source,Player target){return rpgPvp!=null&&rpgPvp.test(source,target);}
 public void interactionPolicy(java.util.function.BiPredicate<UUID,Location> policy){interaction=policy;}
 public boolean interactionAllowed(Player p,Location target){return allowed(p.getUniqueId(),target)&&interaction.test(p.getUniqueId(),target);}
 public boolean writable(Player p){var h=house(p.getWorld());return h.isEmpty()||state==State.READY&&!blocked.contains(h.get().id())&&snapshot.build(p.getUniqueId(),h.get());}
 public void open(Player p){if(ready(p))menu.home(p);else p.sendMessage(Component.text("거주 준비·거래·이동이 끝난 뒤 다시 이용하세요."));}
 public void invalidate(UUID p){var work=busy.get(p);if(work!=null)work.set(false);menu.invalidate(p);}
 public CompletionStage<Void> refresh(){return store.snapshot().thenComposeAsync(s->{snapshot=s;generation++;return protection.common(s);},owner);}
 private <T>CompletionStage<T> execute(Player p,UUID house,Supplier<CompletionStage<T>> job){if(!ready(p)||operation)return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_BUSY"));Object token=boundary.token(p);var live=new AtomicBoolean(true);busy.put(p.getUniqueId(),live);var wrote=new AtomicBoolean(false);changed.put(p.getUniqueId(),wrote);operation=true;if(house!=null)blocked.add(house);boundary.freeze(p,token,true);p.closeInventory();CompletionStage<T> work;try{work=job.get();}catch(Exception error){work=CompletableFuture.failedFuture(error);}return work.whenCompleteAsync((v,error)->{operation=false;busy.remove(p.getUniqueId(),live);changed.remove(p.getUniqueId());boolean refusal=error!=null&&!wrote.get()&&Set.of("ECON_FUNDS","HOUSING_PURCHASE_DISABLED","HOUSING_MEMBERS_FULL","HOUSING_SELF_INVITE","HOUSING_PLOTS_FULL","HOUSING_STALE_OR_OWNER","HOUSING_STALE").contains(io.github.jesterportfolio.hearth.inventory.InventorySaveSession.code(error));if(error==null||refusal){if(house!=null)blocked.remove(house);if(boundary.current(p,token))boundary.freeze(p,token,false);}else{state=State.HOLD;plugin.getLogger().warning("HEARTH_HOUSING_HOLD action=operation");}if(p.isOnline())p.sendMessage(Component.text(error==null?"거주 처리를 완료했습니다.":refusal?"조건이 바뀌었거나 이용 가능한 잔액·구획·정원이 부족합니다. 메뉴에서 다시 확인하세요.":"거주 처리 보류 · 원본과 결제 기록을 보존했습니다."));},owner);}
 private BooleanSupplier live(Player p){var guard=Objects.requireNonNull(busy.get(p.getUniqueId()));return guard::get;}
 public CompletionStage<House> purchase(Player p,int tier,long expected,UUID request){var previous=snapshot.owned(p.getUniqueId());return execute(p,previous.map(House::id).orElse(null),()->provision(economy.context(p),tier,expected,request,live(p),()->changed.get(p.getUniqueId()).set(true)));}
 public CompletionStage<House> provision(io.github.jesterportfolio.hearth.persistence.ServerProgressAccess.Context context,int tier,long expected,UUID request,BooleanSupplier valid,Runnable reserved){return store.reserve(context,request,tier,expected,valid).thenComposeAsync(req->{reserved.run();return store.snapshot().thenComposeAsync(s->{snapshot=s;var h=house(req.house()).orElseThrow();blocked.add(h.id());return worlds.load(h,s,true).thenComposeAsync(w->store.prepared(context,req,w.getUID()),owner).thenComposeAsync(prepared->store.commit(context,req,valid,EconomyStore.Probe.NONE),owner).thenComposeAsync(paid->worlds.apply(paid,snapshot).thenCompose(v->store.activate(context,req)),owner).thenComposeAsync(active->refresh().thenApplyAsync(v->{blocked.remove(active.id());return active;},owner),owner);},owner);},owner);}
 public void updatePlayers(List<UUID> players){snapshot=new Snapshot(snapshot.houses(),snapshot.members(),snapshot.plots(),players,snapshot.catalogs());}
 public CompletionStage<Void> membership(Player p,House h,Supplier<CompletionStage<Void>> action){return execute(p,h.id(),()->action.get().thenComposeAsync(v->{changed.get(p.getUniqueId()).set(true);return refresh();},owner).thenComposeAsync(v->{var current=house(h.id()).orElseThrow();CompletionStage<Void> applied=worlds.loaded().stream().anyMatch(w->worlds.house(w).filter(h.id()::equals).isPresent())?worlds.apply(current,snapshot):CompletableFuture.completedFuture(null);return applied.thenRunAsync(()->{blocked.remove(h.id());for(var player:Bukkit.getOnlinePlayers())if(house(player.getWorld()).filter(home->home.id().equals(h.id())).isPresent()&&!allowed(player.getUniqueId(),player.getLocation()))boundary.returnSpawn(player);},owner);},owner));}
 public void invite(Player p,House h,UUID target,Role role){membership(p,h,()->store.invite(economy.context(p),h.id(),h.revision(),target,role,live(p)));}
 public void accept(Player p,House h,boolean yes){membership(p,h,()->store.accept(economy.context(p),h.id(),h.revision(),yes,live(p)));}
 public void remove(Player p,House h,UUID target){membership(p,h,()->store.remove(economy.context(p),h.id(),h.revision(),target,live(p)));}
 public void claim(Player p){execute(p,null,()->store.claimPlot(economy.context(p),live(p)).thenComposeAsync(id->{changed.get(p.getUniqueId()).set(true);return refresh();},owner));}
 public CompletionStage<Location> target(UUID player,UUID id){var h=house(id).orElseThrow();if(state!=State.READY||blocked.contains(id)||!snapshot.enter(player,h))return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_ENTRY_DENIED"));long revision=h.revision();return worlds.load(h,snapshot,false).thenComposeAsync(w->worlds.apply(h,snapshot),owner).thenApplyAsync(v->{var now=house(id).orElseThrow();if(now.revision()!=revision||blocked.contains(id)||!snapshot.enter(player,now))throw new IllegalStateException("HOUSING_ENTRY_STALE");return worlds.entry(now);},owner);}
 public void enter(Player p,House h){if(ready(p))boundary.move(p,boundary.token(p),"개인 거주",()->target(p.getUniqueId(),h.id()));}
 public void plot(Player p){String id=snapshot.plots().get(p.getUniqueId());var plot=settings.plots().stream().filter(q->q.id().equals(id)).findFirst().orElseThrow();var spawn=boundary.entry(SurvivalWorld.RESIDENCE);var at=spawn.clone().add(plot.x()+plot.width()/2.0,0,plot.z()+plot.width()/2.0);boundary.move(p,boundary.token(p),"기본 거주 구획",()->at.getWorld().getChunkAtAsync(at.getBlockX()>>4,at.getBlockZ()>>4,false).thenApplyAsync(chunk->{if(chunk==null)throw new IllegalStateException("HOUSING_PLOT_CHUNK");at.setY(at.getWorld().getHighestBlockYAt(at.getBlockX(),at.getBlockZ())+1);if(at.getY()<spawn.getY()||at.getY()>=spawn.getY()+plot.height()||!SurvivalWorlds.safe(at))throw new IllegalStateException("HOUSING_PLOT_ENTRY");return at;},owner));}
 public void setHome(Player p,House h){if(!ready(p)||!h.owner().equals(p.getUniqueId()))return;try{worlds.setEntry(h,p.getLocation());p.sendMessage(Component.text("현재 안전한 위치를 집 입장점으로 저장했습니다."));}catch(Exception error){p.sendMessage(Component.text("집 안의 안전한 위치에서 다시 지정하세요."));}}
 public CompletionStage<Void> drain(){if(operation||worlds.busy())return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_DRAIN_BUSY"));if(state!=State.READY)return CompletableFuture.failedFuture(new IllegalStateException("HOUSING_HOLD"));for(var p:Bukkit.getOnlinePlayers())if(house(p.getWorld()).isPresent())p.kick(Component.text("거주 월드 저장·종료 준비"));return worlds.drain().thenRunAsync(()->{try{lease.clean();state=State.DRAINED;}catch(Exception error){state=State.HOLD;throw new CompletionException(error);}},owner);}
 public void console(String[] args,Consumer<String> out){if(Arrays.equals(args,new String[]{"status"}))out.accept("거주="+state+" 소유="+snapshot.houses().size()+" 로드="+worlds.loaded().size()+" 보류="+snapshot.houses().stream().filter(h->h.phase()!=Phase.ACTIVE).count());else if(args.length==3&&args[0].equals("inspect")){try{store.inspect(economy.store.context(economy.settings.realm(),UUID.fromString(args[1])),UUID.fromString(args[2])).whenCompleteAsync((r,e)->out.accept(e==null?"거주 요청="+r:"거주 요청 조회 실패"),owner);}catch(Exception e){out.accept("주민 UUID와 요청 UUID를 확인하세요.");}}else out.accept("housing status|inspect <주민 UUID> <요청 UUID>");}
 @Override public void close(){pulse.cancel();busy.values().forEach(v->v.set(false));menu.close();access.close();if(state!=State.DRAINED)plugin.getLogger().warning("HEARTH_HOUSING_CLOSE HOLD");state=State.CLOSED;}
}
